3: const { context, propagation, trace, metrics, SpanStatusCode } = require('@opentelemetry/api');
4: const { ATTR_ERROR_TYPE } = require('@opentelemetry/semantic-conventions');
5: const cardValidator = require('simple-card-validator');
6: const { v4: uuidv4 } = require('uuid');
7: 
8: const { OpenFeature } = require('@openfeature/server-sdk');
9: const { FlagdProvider } = require('@openfeature/flagd-provider');
10: const flagProvider = new FlagdProvider();
11: 
12: const logger = require('./logger');
13: const tracer = trace.getTracer('payment');
14: const meter = metrics.getMeter('payment');
15: const transactionsCounter = meter.createCounter('demo.payment.transactions', {
16:   unit: '{transaction}',
17: });
18: 
19: const LOYALTY_LEVEL = ['platinum', 'gold', 'silver', 'bronze'];
20: 
21: /** Return random element from given array */
22: function random(arr) {
23:   const index = Math.floor(Math.random() * arr.length);
24:   return arr[index];
25: }
26: 
27: module.exports.charge = async request => {
28:   const span = tracer.startSpan('charge');
29: 
30:   try {
31:     const baggage = propagation.getBaggage(context.active());
32:     const syntheticRequest = baggage?.getEntry('synthetic_request')?.value === 'true';
33: 
34:     if (syntheticRequest) {
35:       span.setAttribute('user_agent.synthetic.type', 'test');
36:     }
37: 
38:     await OpenFeature.setProviderAndWait(flagProvider);
39: 
40:     const numberVariant = await OpenFeature.getClient().getNumberValue("paymentFailure", 0);
41:     const emitRawPii = await OpenFeature.getClient().getBooleanValue("emitRawPii", false);
42: 
43:     if (numberVariant > 0) {
44:       // n% chance to fail with demo.user_context.loyalty_level=gold
45:       if (Math.random() < numberVariant) {
46:         span.setAttributes({'demo.user_context.loyalty_level': 'gold' });
47: 
48:         throw new Error('Payment request failed. Invalid token. demo.user_context.loyalty_level=gold');
49:       }
50:     }
51: 
52:     const {
53:       creditCardNumber: number,
54:       creditCardCvv: cvv,
55:       creditCardExpirationYear: year,
56:       creditCardExpirationMonth: month
57:     } = request.creditCard;
58:     const currentMonth = new Date().getMonth() + 1;
59:     const currentYear = new Date().getFullYear();
60:     const lastFourDigits = number.substr(-4);
61:     const transactionId = uuidv4();
62: 
63:     const card = cardValidator(number);
64:     const { card_type: cardType, valid } = card.getCardDetails();
65: 
66:     const loyalty_level = random(LOYALTY_LEVEL);
67: 
68:     span.setAttributes({
69:       'demo.payment.card_type': cardType,
70:       'demo.payment.card_valid': valid,
71:       'demo.user_context.loyalty_level': loyalty_level,
72:       ...(emitRawPii && {
73:         'demo.payment.card_number': number,
74:         'demo.payment.card_cvv': cvv
75:       })
76:     });
77: 
78:     if (!valid) {
79:       throw new Error('Credit card info is invalid.');
80:     }
81: 
82:     if (!['visa', 'mastercard'].includes(cardType)) {
83:       throw new Error(`Sorry, we cannot process ${cardType} credit cards. Only VISA or MasterCard is accepted.`);
84:     }
85: 
86:     if ((currentYear * 12 + currentMonth) > (year * 12 + month)) {
87:       throw new Error(`The credit card (ending ${lastFourDigits}) expired on ${month}/${year}.`);
88:     }
89: 
90:     // Do not charge synthetic requests.
91:     if (syntheticRequest) {
92:       span.setAttribute('demo.payment.charged', false);
93:     } else {
94:       span.setAttribute('demo.payment.charged', true);
95:     }
96: 
97:     const enduserId = baggage?.getEntry('enduser.id')?.value;
98:     if (enduserId) {
99:       span.setAttribute('enduser.id', enduserId);
100:     }
101: 
102:     const { units, nanos, currencyCode } = request.amount;
103:     logger.info({ transactionId, cardType, lastFourDigits, amount: { units, nanos, currencyCode }, loyalty_level }, 'Transaction complete.');
104:     transactionsCounter.add(1, { 'demo.payment.currency': currencyCode });
105: 
106:     return { transactionId };
107:   } catch (err) {
108:     span.recordException(err);
109:     span.setStatus({ code: SpanStatusCode.ERROR, message: err.message });
110:     span.setAttribute(ATTR_ERROR_TYPE, err.name || 'Error');
111: 
112:     throw err;
113:   } finally {
114:     span.end();
115:   }
116: };

